<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {federationJobsApi as api,type Webhook,type HookDelivery} from '../../infrastructure/federationJobsApi'
const hooks=ref<Webhook[]>([]),deliveries=ref<HookDelivery[]>([]),busy=ref(false),error=ref(''),secret=ref(''),notice=ref(''),url=ref(''),description=ref(''),events=ref(['status.created']),selected=ref(''),state=ref(''),page=ref(1),total=ref(0),hookPage=ref(1),hookTotal=ref(0)
const supported=['status.created','status.updated','status.deleted']
async function load(){busy.value=true;error.value='';try{const [h,d]=await Promise.all([api.hooks(hookPage.value),api.deliveries(page.value,selected.value,state.value)]);hooks.value=h.items||[];hookTotal.value=h.total;deliveries.value=d.items||[];total.value=d.total}catch{error.value='无法读取 Webhook 配置或投递记录。'}finally{busy.value=false}}
async function create(){if(busy.value)return;busy.value=true;error.value='';try{const r=await api.createHook({url:url.value,description:description.value,events:events.value,enabled:true});secret.value=r.secret;url.value='';description.value='';notice.value='已创建订阅，仅接收创建后的公开帖子事件。';await load()}catch{error.value='创建失败，请检查 HTTPS 地址及事件选择。'}finally{busy.value=false}}
async function action(h:Webhook,kind:'enable'|'rotate'|'test'){if(busy.value)return;const prompt=kind==='rotate'?'确认轮换签名密钥？接收方必须同步更新，旧密钥立即失效。':kind==='test'?'确认发送测试事件到已保存的 HTTPS 地址？':`确认${h.enabled?'停用':'启用'}此订阅？`;if(!window.confirm(prompt))return;busy.value=true;error.value='';try{if(kind==='enable')await api.updateHook(h.id,{enabled:!h.enabled});else{const r=await api.hookAction(h.id,kind);if(r.secret)secret.value=r.secret}notice.value=kind==='test'?'测试已进入持久投递队列，请检查下方结果。':'订阅已更新。';await load()}catch{error.value='操作失败，请刷新后重试；测试需要已启用的订阅。'}finally{busy.value=false}}
async function deliveryAction(d:HookDelivery,action:'retry'|'cancel'){if(busy.value||!window.confirm(action==='cancel'?'确认取消此尚未发送的投递？':'确认重新投递？接收方应按相同 Delivery ID 去重。'))return;busy.value=true;try{await api.deliveryAction(d.id,action);await load()}catch{error.value='任务已执行或状态发生变化，请刷新。'}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="admin-page"><header><h1>Webhook</h1><p>仅发送公开、本地且可联邦帖子的创建／更新／删除元数据，不包含正文、私信或访问凭证。HTTPS 目标必须通过网络安全校验。投递最多自动尝试五次；接收方应按 Delivery ID 去重。</p></header><p v-if="error" role="alert" class="admin-error">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><section v-if="secret" class="admin-card"><h2>签名密钥（仅此次显示）</h2><p>请保存到接收方的安全配置，不要公开。关闭后不可再次查看。</p><code>{{ secret }}</code><button class="admin-button" @click="secret=''">已保存，隐藏密钥</button></section><form class="admin-card" @submit.prevent="create"><h2>新建订阅</h2><label class="admin-field">HTTPS 地址<input v-model="url" type="url" required maxlength="2048" placeholder="https://receiver.example/webhook" /></label><label class="admin-field">说明<input v-model="description" maxlength="200" /></label><div class="admin-toolbar"><label v-for="event in supported" :key="event"><input v-model="events" type="checkbox" :value="event" />{{ event }}</label></div><button class="admin-button admin-button--primary" :disabled="busy||!events.length">创建订阅</button></form><section class="admin-card"><h2>订阅</h2><p v-if="!hooks.length&&!busy">尚未配置订阅。</p><article v-for="h in hooks" :key="h.id" class="admin-card"><strong>{{ h.description||h.url }}</strong><p>{{ h.url }}</p><p>{{ h.enabled?'已启用':'已停用' }} · {{ h.events.join('、') }}</p><div class="admin-toolbar"><button class="admin-button" :disabled="busy" @click="action(h,'enable')">{{ h.enabled?'停用':'启用' }}</button><button class="admin-button" :disabled="busy||!h.enabled" @click="action(h,'test')">发送测试事件</button><button class="admin-button" :disabled="busy" @click="action(h,'rotate')">轮换密钥</button></div></article><div class="admin-toolbar"><button class="admin-button" :disabled="busy||hookPage===1" @click="hookPage--;load()">上一页订阅</button><span>第{{ hookPage }}页，共{{ hookTotal }}个</span><button class="admin-button" :disabled="busy||hookPage*30>=hookTotal" @click="hookPage++;load()">下一页订阅</button></div></section><section class="admin-card"><h2>投递结果</h2><form class="admin-toolbar" @submit.prevent="page=1;load()"><label class="admin-field">订阅 ID<input v-model="selected" /></label><label class="admin-field">状态<select v-model="state"><option value="">全部</option><option v-for="value in ['pending','processing','delivered','failed','cancelled']" :key="value">{{ value }}</option></select></label><button class="admin-button" :disabled="busy">查询／刷新</button></form><p v-if="!deliveries.length&&!busy">暂无投递记录。</p><article v-for="d in deliveries" :key="d.id" class="admin-card"><strong>{{ d.event }} · {{ d.state }}</strong><p>Delivery ID：{{ d.id }} · 尝试{{ d.attempts }}次</p><p v-if="d.last_error" class="admin-error">{{ d.last_error }}</p><div v-if="['pending','failed'].includes(d.state)" class="admin-toolbar"><button class="admin-button" :disabled="busy" @click="deliveryAction(d,'retry')">重试</button><button class="admin-button admin-button--danger" :disabled="busy" @click="deliveryAction(d,'cancel')">取消</button></div></article><div class="admin-toolbar"><button class="admin-button" :disabled="busy||page===1" @click="page--;load()">上一页</button><span>第{{ page }}页，共{{ total }}项</span><button class="admin-button" :disabled="busy||page*30>=total" @click="page++;load()">下一页</button></div></section><details class="admin-card"><summary>接收方验签</summary><p>使用保存的密钥，对 Timestamp + '.' + Delivery ID + '.' + 原始请求正文计算 HMAC-SHA256；与 X-Community-Signature（sha256=十六进制摘要）做恒定时间比较。校验时间窗口并持久化 Delivery ID 防重放。</p></details></div></template>
